window.VeilGardeData.files["root"] = {"group":"root","files":[{"path":".gitignore","status":"added","lang":"text","hunks":[[1,0,1,46]],"header":null,"marks":[],"first":1916,"scopes":[],"old":"","new":"# SwiftPM / Xcode\n.build/\n.swiftpm/\nxcuserdata/\n*.xcodeproj\n*.dSYM\nDerivedData/\nPackage.resolved.orig\n\n# Editors and local tooling (CLAUDE.md is a local working file, never committed)\n.vscode/\n.claude/\nCLAUDE.md\n.DS_Store\n__pycache__/\n\n# Weights and Metal libraries stay out of the repo (they go to the work area or an override folder)\n*.safetensors\n*.metallib\n/WeightOverride/\n# ...except the small files the package ships: the test fixtures, the router's prompts and the noiseprint's weights\n!/Tests/**/Fixtures/**/*.safetensors\n!/Sources/VeilGardeFlywheel/Resources/clip_prompts_v1.safetensors\n!/Sources/VeilGardeInference/Resources/noiseprint_v1.safetensors\n\n# The playground's scratch work area (Playground/run.sh)\n/Playground/.work/\n/Playground/.build/\n/Playground/.swiftpm/\n\n# Local only: everything in docs/ but the site (docs/site is the documentation), and the maintainer's own scripts,\n# which need the research environment, Garde or this Mac's layout\n/docs/*\n!/docs/site/\n/scripts/fixtures/\n/scripts/lib.sh\n/scripts/parity-garde.sh\n/scripts/test.sh\n/scripts/weights.sh\n\n# The site regenerates these: exports and check screenshots\n/docs/site/export/\n/docs/site/.check/\n# The ask orb's key, copied from this Mac's ~/.rao by docs/site/src/askkey.py: never committed\n/docs/site/local/\n/Docs/site/local/\n"},{"path":"Package.swift","status":"added","lang":"swift","hunks":[[1,0,1,185]],"header":null,"marks":[],"first":1916,"scopes":[],"old":"","new":"// swift-tools-version: 6.4\n// SPDX-License-Identifier: GPL-3.0-only\n// VeilGarde — the AI-generated-image detector, as one package anyone can train and run: the\n// homography perspective-warp residual lens (the camera-sensor thesis), the models trained on it,\n// the detector that composes them, the flywheel that grows the specialist heads, and a\n// crop-robust watermark read off the same residual.\n//\n// Four products: VeilGarde (everything), VeilGardeInference (the detector alone), VeilWatermark\n// (the signature alone) and the `veilgarde` executable. Eight targets, in layers:\n//   VeilGardeCore       the domain, Foundation + Crypto only, Swift 6 strict: Support/ (JSON,\n//                       hashing, failures, the work area, safetensors, seeded splits), Features/\n//                       (the 19 warp features, capture 9, sharpness 3, the fusion vector), Grid/\n//                       (tile grids, scoring geometry, the weight map, the verdict law), Boost/\n//                       (GBDTModel: the XGBoost JSON codec and evaluator), Heads/ (linear heads,\n//                       the stack combiner, the sensor calibration), Bundle/ (artifacts, the\n//                       manifest, SHA-256 binding), Result/ (InferenceResult, the schema-v2 JSON,\n//                       trust, surfaces, route batches), Store/ (the features-only store)\n//   VeilGardeLens       the extractors, in the order a pixel travels: Image/, Warp/, Features/,\n//                       Capture/, Semantic/ (DINOv2, CLIP vision), Noiseprint/, Scoring/\n//                                                          (MLX through Frigate, Swift 5 mode)\n//   VeilGardeInference  the detector, in the order a verdict is built: Config/, Warp/, Fusion/,\n//                       Specialists/, Route/ (signals, domain heads, mechanisms, the Detector),\n//                       Bundle/ (the shipped artifacts)               (Swift 5 mode, resources)\n//   VeilGardeTraining   the trainers: Data/, Extract/, Boost/ (a native GBDT), Linear/, Warp/,\n//                       Calibration/, Fusion/, Heads/, Combiner/, Noiseprint/, Backbone/\n//                       (DINOv2 and CLIP imports), Recipe/, Engine/, Artifacts/  (Swift 5 mode)\n//   VeilGardeFlywheel   the specialist-head regime: Area/, Store/, Acquire/, Ingest/,\n//                       Candidates/, Battery/, Promote/                          (Swift 5 mode)\n//   VeilWatermark       the crop-robust signature on the warp residual: Signature/, Sections/,\n//                       Match/, Acceptance/                                      (Swift 5 mode)\n//   VeilGarde           the umbrella, and the doctor that checks every layer     (Swift 5 mode)\n//   VeilGardeCLI        the `veilgarde` executable                               (Swift 5 mode)\n//\n// Invariants PackageLayeringTests holds: exactly these four products; MLX only through Frigate\n// (no mlx-swift URL here, and every MLX or Frigate import sits in a target that lists that\n// product); Core imports Foundation and Crypto only; Training never imports Inference or the\n// Flywheel; VeilWatermark imports only Core and Lens; nothing under Sources/ imports MLXLLM,\n// MLXLMCommon, AppKit or UIKit; no type is named like a module; every Swift file opens with a\n// WHAT: header.\n//\n// Frigate, the family's vendored MLX stack, is taken by path, as every consumer in the family\n// takes it: VEILGARDE_FRIGATE_DIR, else ../Frigate, else ../../rao/repositories/Frigate (this\n// Mac's layout). MLX-facing targets use Swift 5 language mode because Frigate's MLX types are not\n// Sendable (Braid's choice).\n\nimport Foundation\nimport PackageDescription\n\nlet v5: [SwiftSetting] = [.swiftLanguageMode(.v5)]\n\n/// Frigate's checkout: the one the environment names, else the first sibling layout that holds one.\nlet frigate: String = {\n    let root = URL(fileURLWithPath: Context.packageDirectory)\n    var candidates: [String] = []\n    if let named = Context.environment[\"VEILGARDE_FRIGATE_DIR\"], !named.isEmpty { candidates.append(named) }\n    candidates += [\"../Frigate\", \"../../rao/repositories/Frigate\"]\n    for candidate in candidates {\n        let url = candidate.hasPrefix(\"/\") ? URL(fileURLWithPath: candidate) : root.appendingPathComponent(candidate)\n        if FileManager.default.fileExists(atPath: url.appendingPathComponent(\"Package.swift\").path) { return candidate }\n    }\n    return \"../Frigate\"\n}()\n\n/// Weights stay out of git but for the noiseprint's (130 KB), which ships in the Inference resources. Copied there,\n/// the DINOv2 files ship inside the bundle too, as Garde's did; otherwise WeightLocator finds them in the work area\n/// or an override folder.\nlet optionalWeights: [Resource] = [\n    \"Resources/dinov2_small.safetensors\",\n    \"Resources/dinov2_small_xsmall.safetensors\",\n    \"Resources/dinov2_small_xxsmall.safetensors\",\n    \"Resources/noiseprint_v1.safetensors\",\n].filter {\n    FileManager.default.fileExists(atPath: Context.packageDirectory + \"/Sources/VeilGardeInference/\" + $0)\n}.map { .copy($0) }\n\nlet package = Package(\n    name: \"VeilGarde\",\n    platforms: [.macOS(\"26.0\")],\n    products: [\n        .library(name: \"VeilGarde\", targets: [\"VeilGarde\"]),\n        .library(name: \"VeilGardeInference\", targets: [\"VeilGardeInference\"]),\n        .library(name: \"VeilWatermark\", targets: [\"VeilWatermark\"]),\n        .executable(name: \"veilgarde\", targets: [\"VeilGardeCLI\"]),\n    ],\n    dependencies: [\n        .package(path: frigate),\n        .package(url: \"https://github.com/apple/swift-argument-parser\", from: \"1.3.0\"),\n        .package(url: \"https://github.com/apple/swift-crypto.git\", from: \"4.2.0\"),\n    ],\n    targets: [\n        .target(\n            name: \"VeilGardeCore\",\n            dependencies: [.product(name: \"Crypto\", package: \"swift-crypto\")]\n        ),\n        .target(\n            name: \"VeilGardeLens\",\n            dependencies: [\n                \"VeilGardeCore\",\n                .product(name: \"MLX\", package: \"Frigate\"),\n                .product(name: \"MLXNN\", package: \"Frigate\"),\n                .product(name: \"MLXFFT\", package: \"Frigate\"),\n                .product(name: \"MLXAccelerate\", package: \"Frigate\"),\n                // FrigateBoost's XGBoostTreeModel, the evaluator Garde scores tiles with.\n                .product(name: \"Frigate\", package: \"Frigate\"),\n            ],\n            swiftSettings: v5\n        ),\n        .target(\n            name: \"VeilGardeInference\",\n            dependencies: [\"VeilGardeLens\"],\n            // The shipped bundle: the shipped artifacts, by name (the result JSON reports\n            // the warp models' hashes; the calibration is bound to the sensor model's bytes), bound\n            // by manifest.json. Weights are gitignored but for the noiseprint's, and resolved at run\n            // time (WeightLocator); copied into this folder they ship inside the bundle.\n            resources: [\n                .copy(\"Resources/manifest.json\"),\n                .copy(\"Resources/warp_tile32.xgb.json\"),\n                .copy(\"Resources/warp_majority_tile32.xgb.json\"),\n                .copy(\"Resources/warp_sensor_calibration.json\"),\n                .copy(\"Resources/fusion_head.xgb.json\"),\n                .copy(\"Resources/fusion_ref.xgb.json\"),\n                .copy(\"Resources/stack_combiner_v2.json\"),\n                .copy(\"Resources/xdomain_centroids_v0.json\"),\n                .copy(\"Resources/screenshot_dinov2_v1.10.json\"),\n                .copy(\"Resources/art_dinov2_v2.json\"),\n                .copy(\"Resources/blur_dinov2_v1.json\"),\n                .copy(\"Resources/human_dinov2_v4.json\"),\n                .copy(\"Resources/semtile_dinov2_v1.json\"),\n                .copy(\"Resources/cgi_dinov2_v1.json\"),\n                .copy(\"Resources/preview_dinov2_v1.json\"),\n            ] + optionalWeights,\n            swiftSettings: v5\n        ),\n        .target(\n            name: \"VeilGardeTraining\",\n            dependencies: [\n                \"VeilGardeLens\",\n                .product(name: \"MLX\", package: \"Frigate\"),\n                .product(name: \"MLXNN\", package: \"Frigate\"),\n                .product(name: \"MLXOptimizers\", package: \"Frigate\"),\n                .product(name: \"FrigateHub\", package: \"Frigate\"),\n            ],\n            swiftSettings: v5\n        ),\n        .target(\n            name: \"VeilGardeFlywheel\",\n            dependencies: [\"VeilGardeTraining\", \"VeilGardeInference\"],\n            // The battery's spec and ratchet floors, byte for byte (`flywheel init` copies them into\n            // the work area, where the battery reads them); the category router's prompt matrix;\n            // the collector jobs that fill each blind spot.\n            resources: [\n                .copy(\"Resources/battery_spec_v2.json\"),\n                .copy(\"Resources/battery_v2_baseline.json\"),\n                .copy(\"Resources/clip_prompts_v1.safetensors\"),\n                .copy(\"Resources/acquire_targets_v1.json\"),\n            ],\n            swiftSettings: v5\n        ),\n        .target(\n            name: \"VeilWatermark\",\n            dependencies: [\"VeilGardeLens\"],\n            swiftSettings: v5\n        ),\n        .target(\n            name: \"VeilGarde\",\n            dependencies: [\"VeilGardeInference\", \"VeilGardeTraining\", \"VeilGardeFlywheel\", \"VeilWatermark\"],\n            swiftSettings: v5\n        ),\n        .executableTarget(\n            name: \"VeilGardeCLI\",\n            dependencies: [\n                \"VeilGarde\",\n                .product(name: \"ArgumentParser\", package: \"swift-argument-parser\"),\n            ],\n            swiftSettings: v5\n        ),\n        .testTarget(name: \"VeilGardeCoreTests\", dependencies: [\"VeilGardeCore\"], exclude: [\"Fixtures\"]),\n        .testTarget(name: \"VeilGardeLensTests\", dependencies: [\"VeilGardeLens\"], exclude: [\"Fixtures\"], swiftSettings: v5),\n        .testTarget(name: \"VeilGardeInferenceTests\", dependencies: [\"VeilGardeInference\"], exclude: [\"Fixtures\"], swiftSettings: v5),\n        .testTarget(name: \"VeilGardeTrainingTests\", dependencies: [\"VeilGardeTraining\"], exclude: [\"Fixtures\"], swiftSettings: v5),\n        .testTarget(name: \"VeilGardeFlywheelTests\", dependencies: [\"VeilGardeFlywheel\"], swiftSettings: v5),\n        .testTarget(name: \"VeilWatermarkTests\", dependencies: [\"VeilWatermark\"], swiftSettings: v5),\n        .testTarget(name: \"VeilGardeCLITests\", dependencies: [\"VeilGardeCLI\"], swiftSettings: v5),\n    ]\n)\n"},{"path":"README.md","status":"added","lang":"markdown","hunks":[[1,0,1,64]],"header":null,"marks":[],"first":1916,"scopes":[],"old":"","new":"[![VeilGarde: every tile, sixteen warps, one verdict. An image's 16 by 16 tiles, coloured by how generated each reads, run through sixteen warps and out as the camera-sensor score, the fusion base and the stacked verdict, ending in a gold mark.](README_Assets/hero.png)](README_Assets/hero.png)\n\n# VeilGarde\n\nVeilGarde is a detector for AI-generated images, with a crop-robust watermark, as one Swift package you can train and run on a Mac. [Veil](https://veil.rao.nyc) is the pipeline, [Veil8](https://github.com/riteshpakala/Veil8) the PPM, VeilGarde the detection and watermarking.\n\nIt starts from one physical idea, the **warp lens**. Every 32×32 tile of an image is perspective-warped through 16 fixed homographies and back. A camera sensor's mosaic and noise do not survive the round trip the way a generator's output does, and the residual, with its seams, correlations and demosaic statistics, is scored tile by tile. That gives two calls: the **camera-sensor score**, whether a real camera made these pixels, and the **weighted verdict**, how generated the image looks where it matters.\n\nAround the lens sit the models that made it robust: a fusion head over DINOv2 semantics and the capture signature, specialist heads for art, blur, faces, renders and screenshots, a stacked combiner, and a flywheel that keeps growing the heads without ever storing an image. A crop-robust signature is read off the same residual.\n\n| Subpackage | Holds |\n|---|---|\n| `VeilGardeCore` | the domain, with no MLX: features, grids and the verdict law, the XGBoost codec, heads, bundles, the result JSON, the feature store |\n| `VeilGardeLens` | the extractors: the warp residual and its 19 features, capture, DINOv2, CLIP, noiseprint |\n| `VeilGardeInference` | the detector: the camera-sensor score, the fusion base, the specialist stack, the router, the verdict |\n| `VeilGardeTraining` | the trainers for every shipped model, driven by a recipe DSL, and the backbone imports |\n| `VeilGardeFlywheel` | acquisition into a features-only store, candidates, the battery, promote and rollback |\n| `VeilWatermark` | a crop-robust signature read off the per-tile fragility pattern |\n| `veilgarde` | the CLI over all of it |\n\n## The CLI at a glance\n\n```sh\nscripts/cli.sh doctor                                   # builds veilgarde, installs MLX's Metal library, checks the setup\nscripts/cli.sh score photo.jpg                          # the warp lens alone: camera-sensor score, weighted verdict\nscripts/cli.sh route photo.jpg --json                   # the full detector, Garde's schema-v2 result\nscripts/cli.sh train plan --preset ~/datasets/final_mixed  # what the shipped recipe would train, without training\nVEILGARDE_CONFIG=release scripts/cli.sh train heads     # a candidate bundle under <work area>/candidates/\nscripts/cli.sh flywheel init && scripts/cli.sh flywheel battery --gate full\nVEILGARDE_CONFIG=release scripts/cli.sh research prune   # what the system could do without, measured on held-out data\nscripts/cli.sh watermark sign photo.jpg > photo.vw1 && scripts/cli.sh watermark match crop.jpg photo.vw1\n```\n\n`scripts/cli.sh` builds `veilgarde`, installs `mlx.metallib` beside it, and finds Frigate. `scripts/cli.sh <command> --help` lists a command's flags.\n\n## The playground\n\n[Playground/](Playground/README.md) runs both regimes on this Mac in one program and exits 0 only when every checkpoint holds: one image through the lens, the camera-sensor score, the capture signature, the fusion base, the specialist stack and the combiner's arithmetic term by term, then each trainer in miniature, the flywheel's promote and rollback, and the watermark. [The site's chapter 9](docs/site/09-playground.html) walks through it.\n\n```sh\nPlayground/run.sh\n```\n\n## VeilGarde docsite\n\nA site that explains each layer and shows every file this build changed, verbatim, with each Swift declaration's calls and callers, and the run's ledger of commands, tests and decisions. Eleven trails walk the code in the order it runs: how the warp model, the fusion head, the specialist heads and the noiseprint are each trained, how each feeds the final verdict at inference, how the watermark signs an image and matches a crop of it, and the pruning study. A grid picks them, a row for each flow and a column for each kind. Double-click scripts/site.command, or open [docs/site/index.html](docs/site/index.html); it is plain HTML with no build step. [docs/site/README.md](docs/site/README.md) says how it is rebuilt and checked.\n\nThe site's chat asks Mistral about what you are reading. On a Mac that holds a Mistral key in its key store, `scripts/site.command` hands the site that key; anyone else is asked for their own key in a dialog when the chat opens, and it stays in their browser.\n\n## Requirements and tests\n\n- Xcode 27 (Swift 6.4), macOS 26, Apple silicon.\n- [Frigate](https://github.com/rao-studios/Frigate), the family's MLX stack, checked out beside this repo or named by `VEILGARDE_FRIGATE_DIR`.\n- A work area, the folder `VEILGARDE_WORK_AREA` (or `--work-area`) names: the live bundle, the weights, the feature store, candidates and the battery. VeilGarde writes nowhere else. Datasets live under `VEILGARDE_DATASETS`, else the work area's `datasets/`.\n- The weights, in the work area's `weights/`: `veilgarde weights import-dinov2` builds DINOv2's from Hugging Face's checkpoint, and `veilgarde weights import-clip` CLIP's vision tower for acquisition. The noiseprint's weights, 130 KB, ship with the package.\n- Tests: `swift build --build-tests`, then `./build-metallib.sh debug` to put MLX's Metal library into the test bundles, then `VEILGARDE_MLX_TESTS=1 swift test --skip-build --no-parallel` (without `VEILGARDE_MLX_TESTS`, only the CPU suites run). Before the next test build, delete the `mlx.metallib` copies inside `.build`'s `.xctest` bundles: a bundle that holds one fails to re-sign.\n\nInside each target, folders follow the order of operations. The site's chapters walk them, and its change explorer shows every file.\n\n## Where it came from\n\nVeilGarde consolidates the detector's research into one tool. Its inference reproduces Garde's, ([CLR](https://rao.nyc/thoughts/2026-04-25), [CLR (Journey)](https://paka.la/blog/clr-journey)), the R&D it supersedes; its trainers reproduce the research's Python recipes, whose numbers it quotes with their dates. It takes MLX from Frigate, and its layout, recipes, docs site and explorer from Braid.\n\nGNU General Public License v3.0 (see [LICENSE](LICENSE)).\n"},{"path":"build-metallib.sh","status":"added","lang":"shell","hunks":[[1,0,1,34]],"header":{"lines":[2,12],"style":"hash","what":[3,3],"pin":[6,11],"in":[4,4],"out":[5,5]},"marks":[],"first":1916,"scopes":[],"old":"","new":"#!/usr/bin/env bash\n# SPDX-License-Identifier: GPL-3.0-only\n# WHAT: Build MLX's mlx.metallib into this package's .build.\n# IN:   [debug|release] (default debug). VEILGARDE_FRIGATE_DIR overrides where Frigate lives.\n# OUT:  mlx.metallib beside every VeilGarde binary and inside every .xctest bundle.\n# PIN:  A delegate, not an implementation. Frigate owns the vendored .metal sources, so it owns the\n#       compile; `swift build` has no Metal step, and without this script the first GPU op dies\n#       with \"Failed to load the default metallib\". Run it after `swift build` (or\n#       `swift build --build-tests`), because it installs into the existing .build tree.\n#\n#   ./build-metallib.sh [debug|release]\n#\nset -euo pipefail\n\nREPO_ROOT=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\n# Frigate, the vendored MLX stack, is taken by path: VEILGARDE_FRIGATE_DIR, else a checkout beside this repo\n# (https://github.com/rao-studios/Frigate). A machine's own settings, kept in a gitignored scripts/lib.sh, come first.\n[ -f \"$REPO_ROOT/scripts/lib.sh\" ] && source \"$REPO_ROOT/scripts/lib.sh\"\nVEILGARDE_FRIGATE_DIR=\"${VEILGARDE_FRIGATE_DIR:-$REPO_ROOT/../Frigate}\"\nif [ ! -f \"$VEILGARDE_FRIGATE_DIR/Package.swift\" ]; then\n    echo \"veilgarde: no Frigate at $VEILGARDE_FRIGATE_DIR: check it out beside this repo, or set VEILGARDE_FRIGATE_DIR\" >&2\n    exit 69\nfi\nexport VEILGARDE_FRIGATE_DIR=\"$(cd \"$VEILGARDE_FRIGATE_DIR\" && pwd)\"\nexport GIT_LFS_SKIP_SMUDGE=1    # Frigate's LFS fixtures break SwiftPM checkouts otherwise\nCANONICAL=\"$VEILGARDE_FRIGATE_DIR/scripts/build-metallib.sh\"\n\nif [ ! -x \"$CANONICAL\" ]; then\n    echo \"build-metallib: cannot find $CANONICAL\" >&2\n    echo \"  Set VEILGARDE_FRIGATE_DIR to your Frigate checkout.\" >&2\n    exit 1\nfi\n\nexec \"$CANONICAL\" \"${1:-debug}\" --package \"$REPO_ROOT\"\n"}]};
